/// <summary>
/// PaffH 06.12.21
/// get privilege info in batch mode
/// </summary>
class NDXPrivilegeInfoSysOperationsService
    extends SysOperationServiceBase
{
    boolean getPrivilegeInfo;


}

Method.Source:
/// <summary>
/// PaffH 06.12.21
/// init from contract
/// </summary>
/// <param name = "_contract">NDXPrivilegeInfoContract</param>
protected void InitFromContract(NDXPrivilegeInfoContract _contract)
{
    getPrivilegeInfo = _contract.parmGetPrivilegeInfo();
}

/// <summary>
/// PaffH 06.12.21
/// get the privilege infos
/// </summary>
protected void GetPrivilegeInfo()
{
    NDXPrivilegeManagement::main(new Args());
}

/// <summary>
/// PaffH 06.12.21
/// validate 
/// </summary>
/// <returns>boolean</returns>
public boolean Validate()
{
    return true;
}

/// <summary>
/// PaffH 06.12.21
/// run logic
/// </summary>
/// <param name = "_contract">NDXPrivilegeInfoContract</param>
public void process(NDXPrivilegeInfoContract _contract)
{
    if (!_contract.validate())
    {
        return;
    }
    this.InitFromContract(_contract);
    if (!this.Validate())
    {
        return;
    }
    this.GetPrivilegeInfo();

}
